import { SettingsSidebar } from '@/components/settings/SettingsSidebar'
import { SettingsMobileNav } from '@/components/settings/SettingsMobileNav'

/**
 * Settings hub layout — Stripe/Vercel sidebar pattern.
 *
 * Desktop (≥ lg): Fixed 240px sidebar on left, scrollable content max-720px centered.
 * Mobile (< lg):  <SettingsMobileNav> select above content — Stripe mobile pattern.
 *
 * S14: Rewired to new /settings/{group}/{section} URL structure.
 */
export default function SettingsLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-[calc(100vh-57px)]">
      {/* Desktop sidebar — 240px fixed width */}
      <aside className="hidden lg:block border-r border-border/60 bg-background shrink-0">
        <SettingsSidebar />
      </aside>

      {/* Content area */}
      <div className="flex-1 min-w-0">
        {/* Mobile section switcher (hidden on lg+) */}
        <div className="lg:hidden border-b border-border/60 bg-background px-4 py-3">
          <SettingsMobileNav />
        </div>

        {/* Page content */}
        <main id="main-content" className="max-w-[720px] mx-auto px-6 py-8">
          {children}
        </main>
      </div>
    </div>
  )
}

'use client'

import { usePathname, useRouter } from 'next/navigation'

interface Section {
  label: string
  href: string
  group: string
}

const SECTIONS: Section[] = [
  // Studio
  { group: 'Studio', label: 'Profile',            href: '/settings/studio/profile'       },
  { group: 'Studio', label: 'Branding',           href: '/settings/studio/branding'      },
  { group: 'Studio', label: 'Services',           href: '/settings/studio/services'      },
  { group: 'Studio', label: 'Booking policies',   href: '/settings/studio/policies'      },
  { group: 'Studio', label: 'Ink registry',       href: '/settings/studio/ink-registry'  },
  { group: 'Studio', label: 'Booking page',       href: '/settings/studio/booking-page'  },
  // Team
  { group: 'Team',   label: 'Members',            href: '/settings/team/members'         },
  { group: 'Team',   label: 'Roles & permissions', href: '/settings/team/permissions'    },
  // Subscription
  { group: 'Subscription', label: 'Plan & billing', href: '/settings/subscription/billing' },
  { group: 'Subscription', label: 'Usage',           href: '/settings/subscription/usage'   },
  // Integrations
  { group: 'Integrations', label: 'Connected apps', href: '/settings/integrations' },
  // Account
  { group: 'Account', label: 'My profile', href: '/settings/account/profile'  },
  { group: 'Account', label: 'Advanced',   href: '/settings/account/advanced' },
]

const GROUPS = ['Studio', 'Team', 'Subscription', 'Integrations', 'Account'] as const

export function SettingsMobileNav() {
  const pathname = usePathname()
  const router = useRouter()

  // Match current section — exact or prefix
  const current = SECTIONS.find(
    (s) => pathname === s.href || pathname.startsWith(s.href + '/'),
  )

  function handleChange(e: React.ChangeEvent<HTMLSelectElement>) {
    router.push(e.target.value)
  }

  return (
    <label htmlFor="settings-section-select" className="block">
      <span className="sr-only">Settings section</span>
      <select
        id="settings-section-select"
        className="block w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground shadow-soft focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        value={current?.href ?? '/settings/studio/profile'}
        onChange={handleChange}
        aria-label="Navigate to settings section"
      >
        {GROUPS.map((group) => (
          <optgroup key={group} label={group}>
            {SECTIONS.filter((s) => s.group === group).map((s) => (
              <option key={s.href} value={s.href}>
                {s.label}
              </option>
            ))}
          </optgroup>
        ))}
      </select>
    </label>
  )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  Building2,
  Palette,
  FileText,
  Users,
  Shield,
  Scissors,
  FlaskConical,
  Plug,
  Globe,
  CreditCard,
  BarChart3,
  UserCircle,
} from 'lucide-react'
import { cn } from '@/lib/utils'

interface NavItem {
  label: string
  href: string
  icon: React.ElementType
  badge?: string
}

interface NavGroup {
  label: string
  items: NavItem[]
}

const NAV_GROUPS: NavGroup[] = [
  {
    label: 'Studio',
    items: [
      { label: 'Profile',          href: '/settings/studio/profile',      icon: Building2    },
      { label: 'Branding',         href: '/settings/studio/branding',     icon: Palette      },
      { label: 'Services',         href: '/settings/studio/services',     icon: Scissors     },
      { label: 'Booking policies', href: '/settings/studio/policies',     icon: FileText     },
      { label: 'Ink registry',     href: '/settings/studio/ink-registry', icon: FlaskConical },
      { label: 'Booking page',     href: '/settings/studio/booking-page', icon: Globe        },
    ],
  },
  {
    label: 'Team',
    items: [
      { label: 'Members',             href: '/settings/team/members',      icon: Users  },
      { label: 'Roles & permissions', href: '/settings/team/permissions',  icon: Shield },
    ],
  },
  {
    label: 'Subscription',
    items: [
      { label: 'Plan & billing', href: '/settings/subscription/billing', icon: CreditCard },
      { label: 'Usage',          href: '/settings/subscription/usage',   icon: BarChart3  },
    ],
  },
  {
    label: 'Integrations',
    items: [
      { label: 'Connected apps', href: '/settings/integrations', icon: Plug },
    ],
  },
  {
    label: 'Account',
    items: [
      { label: 'My profile', href: '/settings/account/profile',  icon: UserCircle                    },
      { label: 'Advanced',   href: '/settings/account/advanced', icon: Shield, badge: 'danger' },
    ],
  },
]

export function SettingsSidebar() {
  const pathname = usePathname()

  return (
    <nav
      className="w-[240px] shrink-0 sticky top-[57px] h-[calc(100vh-57px)] overflow-y-auto py-4 px-3"
      aria-label="Settings navigation"
    >
      {NAV_GROUPS.map((group) => (
        <div key={group.label} className="mb-2">
          <p className="text-[11px] font-semibold text-muted-foreground/60 px-2 mb-1 mt-5 first:mt-2">
            {group.label}
          </p>
          <div className="space-y-0.5">
            {group.items.map((item) => {
              const isActive =
                pathname === item.href ||
                pathname.startsWith(item.href + '/')

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  aria-current={isActive ? 'page' : undefined}
                  className={cn(
                    'flex min-h-[36px] items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium transition-colors duration-[120ms]',
                    isActive
                      ? 'bg-accent text-accent-foreground'
                      : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground',
                  )}
                >
                  <item.icon
                    className="size-4 shrink-0 text-muted-foreground/70"
                    aria-hidden="true"
                  />
                  {item.label}
                  {item.badge !== undefined && (
                    <span
                      className={cn(
                        'ml-auto text-[10px] rounded px-1 py-0.5',
                        item.badge === 'danger'
                          ? 'bg-destructive/10 text-destructive'
                          : 'text-muted-foreground',
                      )}
                    >
                      {item.badge === 'danger' ? '!' : item.badge}
                    </span>
                  )}
                </Link>
              )
            })}
          </div>
        </div>
      ))}
    </nav>
  )
}

import { redirect } from 'next/navigation'

// Settings hub root — redirect to canonical landing section
export default function SettingsIndexPage() {
  redirect('/settings/studio/profile')
}

'use client'

import { useRef, useCallback, useState } from 'react'

export type AutoSaveStatus = 'idle' | 'saving' | 'saved' | 'error'

interface UseDebouncedAutoSaveOptions<T> {
  /** Async save function. Receives the current form value. Throws on failure. */
  onSave: (value: T) => Promise<void>
  /** Debounce delay in ms. Default: 800. */
  delay?: number
}

interface UseDebouncedAutoSaveReturn<T> {
  status: AutoSaveStatus
  lastSavedAt: Date | null
  /** Call on every field change. Schedules a debounced save. */
  handleChange: (value: T) => void
  /** Call on field blur for immediate save (cancels pending debounce). */
  handleBlur: (value: T) => Promise<void>
}

export function useDebouncedAutoSave<T>({
  onSave,
  delay = 800,
}: UseDebouncedAutoSaveOptions<T>): UseDebouncedAutoSaveReturn<T> {
  const [status, setStatus] = useState<AutoSaveStatus>('idle')
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const save = useCallback(
    async (value: T) => {
      setStatus('saving')
      try {
        await onSave(value)
        setStatus('saved')
        setLastSavedAt(new Date())
      } catch {
        setStatus('error')
      }
    },
    [onSave],
  )

  const handleChange = useCallback(
    (value: T) => {
      if (timerRef.current) clearTimeout(timerRef.current)
      timerRef.current = setTimeout(() => {
        void save(value)
      }, delay)
    },
    [save, delay],
  )

  const handleBlur = useCallback(
    async (value: T) => {
      if (timerRef.current) {
        clearTimeout(timerRef.current)
        timerRef.current = null
      }
      await save(value)
    },
    [save],
  )

  return { status, lastSavedAt, handleChange, handleBlur }
}
